// Seed content for the P0 loop. Only Mathematics has real cards for now —
// every other subject is listed (so Home/Progress show the full CBC subject
// set) but starts empty until a content-source decision is made.
//
// Bump SEED_VERSION whenever this file's cards change. On next launch,
// db.ts wipes and re-inserts the `cards` table when the device's stored
// seed_version is behind — so content edits actually reach devices that
// already seeded an earlier version, without wiping grade/streak/stars.

export const SEED_VERSION = 14;

export type Subject = {
  id: string;
  name: string;
  emoji: string;
};

export const SUBJECTS: Subject[] = [
  { id: 'math', name: 'Mathematics', emoji: '🔢' },
  { id: 'english', name: 'English', emoji: '🔤' },
  { id: 'kiswahili', name: 'Kiswahili', emoji: '🗣️' },
  { id: 'science', name: 'Integrated Science', emoji: '🔬' },
  { id: 'social', name: 'Social Studies', emoji: '🌍' },
  { id: 'creative', name: 'Creative Arts', emoji: '🎨' },
  { id: 're', name: 'Religious Education', emoji: '📖' },
];

export type SeedCard = {
  id: string;
  subjectId: string;
  grade: number;
  topic: string;
  question: string;
  options: string[];
  correctIndex: number;
  explanation: string;
};

// A short readable explainer per (grade, subject, topic) — the "Read"
// counterpart to that topic's practice cards. Piloting with Mathematics
// only; other subjects' topics have cards but no notes yet.
export type SeedNote = {
  id: string;
  subjectId: string;
  grade: number;
  topic: string;
  title: string;
  body: string;
};

