    title: 'Christian Values',
    body: "In the Sermon on the Mount, Jesus taught the Beatitudes — a set of blessings describing qualities like being merciful and being a peacemaker as blessed, even though the world doesn't always value them.\n\nChristian teaching also describes the 'fruits of the Spirit' — qualities like love, joy, peace, and patience that are meant to grow in a person's character as they live out their faith.\n\nIntegrity means being honest and having strong moral principles, even when no one is watching — doing what is right consistently, not just when convenient. Justice means treating everyone fairly and standing up for what is right, an important value connected to Christian teaching about loving one's neighbour.\n\nLiving out the Beatitudes and fruits of the Spirit — like being a peacemaker who helps resolve conflicts peacefully — reflects these values in everyday actions, not just in words.",
