    title: 'Prayer & Worship',
    body: "Fasting is the practice of voluntarily going without food (or certain other things) for a period of time, as a way of focusing spiritually and drawing closer to God. Baptism is a Christian rite that symbolises a person's commitment to their Christian faith.\n\nChristians observe practices like fasting and prayer, often together as a community, in order to grow spiritually and strengthen their relationship with God.\n\nChristianity includes many different denominations — traditions that share core beliefs but may worship in different ways. Understanding these different worship traditions helps build respect and understanding among different Christian communities, rather than causing unnecessary division.\n\nDespite differences in style, a common purpose across denominations is communal worship — coming together to praise God and support one another in faith.",
